  if (score < 0.3) return { label: 'Clear', cls: 'ok', why, tip: 'Good for lures, squid, mullet and wrasse. Fish lighter line and natural colours; fish see more, so dawn, dusk and night are best.' };
  if (score < 0.6) return { label: 'Slightly coloured', cls: 'warn', why, tip: 'Good for most fishing, and often the best water for bass. Bait or lures both work.' };
