function applyPack() {
  const rg = region(), p = rg === 'pt' ? 'pt' : rg === 'mad' ? 'mad' : 'uk';
  PACK = p; FISH = p === 'pt' ? FISH_PT : p === 'mad' ? FISH_MAD : FISH_UK;
  if (TARGET && !FISH.some(f => f.n === TARGET)) { const old = FISH_UK.concat(FISH_PT, FISH_MAD).find(f => f.n === TARGET), key = old ? (old.k || old.n) : TARGET, t = FISH.find(f => (f.k || f.n) === key); TARGET = t ? t.n : ''; }
  if ($('l-sp')) { const cur = $('l-sp').value; $('l-sp').innerHTML = FISH.map(f => `<option>${f.n}</option>`).join('') + '<option>Other</option>'; if ([...$('l-sp').options].some(o => o.value === cur)) $('l-sp').value = cur; $('l-baits').innerHTML = [...new Set(FISH.flatMap(f => f.bait))].map(b => `<option value="${b}"></option>`).join(''); }
}
