const DOW_PT = { Today: 'Hoje', Mon: 'Seg', Tue: 'Ter', Wed: 'Qua', Thu: 'Qui', Fri: 'Sex', Sat: 'Sáb', Sun: 'Dom' };
const MON_PT = { Jan: 'jan', Feb: 'fev', Mar: 'mar', Apr: 'abr', May: 'mai', Jun: 'jun', Jul: 'jul', Aug: 'ago', Sep: 'set', Oct: 'out', Nov: 'nov', Dec: 'dez' };
const CMP_PT = { N: 'N', NNE: 'NNE', NE: 'NE', ENE: 'ENE', E: 'E', ESE: 'ESE', SE: 'SE', SSE: 'SSE', S: 'S', SSW: 'SSO', SW: 'SO', WSW: 'OSO', W: 'O', WNW: 'ONO', NW: 'NO', NNW: 'NNO' };
const dateWords = s => s.replace(/\b(Today|Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b/g, w => DOW_PT[w]).replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b/g, w => MON_PT[w]);
const lc1 = s => s.charAt(0).toLowerCase() + s.slice(1), uc1 = s => s.charAt(0).toUpperCase() + s.slice(1);
Object.assign(PT, { 'approximate (can be up to # h out)': 'aproximado (pode falhar até # h)', 'South East England': 'Sudeste de Inglaterra', 'South West England': 'Sudoeste de Inglaterra', 'London & South East England': 'Londres e Sudeste de Inglaterra', 'Language': 'Idioma' });
const PT_RX = [
  [/^(Today|Mon|Tue|Wed|Thu|Fri|Sat|Sun)((?: \d{1,2})?(?: (?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec))?(?: \d{1,2}:\d\d| \d{4})?)$/, (m, d, r) => DOW_PT[d] + dateWords(r)],
  [/^(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)$/, (m, d, mo) => d + ' ' + MON_PT[mo]],
  [/^(\(?)(N|NNE|NE|ENE|E|ESE|SE|SSE|S|SSW|SW|WSW|W|WNW|NW|NNW) (\d+) mph(?:, gusts (\d+))?(\)?)$/, (m, a, c, w, g, b) => `${a}${CMP_PT[c]} ${w} mph${g ? ', rajadas ' + g : ''}${b}`],
  [/^(NNE|ENE|ESE|SSE|SSW|SW|WSW|W|WNW|NW|NNW)$/, (m, c) => CMP_PT[c]],
  [/^(.+) isn't usually about in (\w+)\. These are still the best conditions for it this week\.$/, (m, f, mo) => `${tr(f)} não costuma andar por cá em ${tr(mo)}. Mesmo assim, estas são as melhores condições para ele esta semana.`],
  [/^Nearest marks for (.+)$/, (m, f) => `Marcas mais perto · ${tr(uc1(f))}`],
  [/^Biting well in (\w+)$/, (m, mo) => `A dar bem em ${tr(mo)}`],
  [/^(\d+) species about in (\w+)$/, (m, n, mo) => `${n} espécies por cá em ${tr(mo)}`],
  [/^All (\d+) species · (\w+) highlighted$/, (m, n, mo) => `Todas as ${n} espécies · ${tr(mo)} em destaque`],
  [/^Best marks for (\w+), ranked by fish in season$/, (m, mo) => `Melhores marcas para ${tr(mo)}, por peixes na época`],
  [/^(Wind in your face|Wind at your back|Crosswind) at (.+)$/, (m, a, b) => `${tr(a)} em ${b}`],
  [/^(.+) at (dusk|dawn)$/, (m, a, b) => `${tr(a)} ao ${b === 'dusk' ? 'anoitecer' : 'amanhecer'}`],
  [/^(Yellow|Amber|Red) warning of (.+) affecting (.+)$/, (m, l, k, a) => `Aviso ${tr(l).toLowerCase()} de ${tr(k)}: ${tr(a)}`],
  [/^(Met Office|IPMA) warning(?:: (.+))?$/, (m, s, k) => `Aviso ${s}${k ? ': ' + tr(k) : ''}`],
  [/^Valid from (.+?) to (.+?)(\. .*|)$/s, (m, a, b, r) => `Válido de ${dateWords(a)} a ${dateWords(b)}${r}`],
  [/^Pressure (\d+) hPa, (falling slowly|falling fast|rising slowly|rising fast|steady)(?: \(([-+]?[\d.]+) in (\d+) h\))?$/, (m, p, w, d, h) => `Pressão ${p} hPa, ${tr(w)}${d ? ` (${d} em ${h} h)` : ''}`],
  [/^Tides · (.+)$/, (m, a) => `Marés · ${a}`],
  [/^Ocean model for (.+)$/, (m, a) => `Modelo do oceano para ${a}`],
  [/^Southampton tide times \((.+) may differ by up to ~(\d+) min\)$/, (m, a, n) => `Marés de Southampton (${a} pode diferir até ~${n} min)`],
  [/^\(Admiralty: (.+)\)$/, (m, a) => `(Admiralty: ${a})`],
  [/^(.+) must be returned\. Logged as a catch-and-release record\.$/, (m, f) => `${tr(f)} tem de ser devolvido. Ficou registado como captura e devolução.`],
  [/^Careful: ([\d.]+) cm is under the (.+) legal size for (.+)\. It has to go back\.$/, (m, l, s, f) => `Atenção: ${l} cm está abaixo do mínimo legal de ${s} para ${tr(f)}. Tem de ser devolvido.`],
  [/^Backup saved to your downloads \((\d+) catches with photos, (\d+) saved spots\)\. Keep it in Google Drive or email it to yourself\.$/, (m, c, s) => `Cópia guardada nas transferências (${c} capturas com fotografias, ${s} locais guardados). Guarda-a no Google Drive ou envia-a para o teu email.`],
  [/^Restored (\d+) saved spots?\. (.*)$/, (m, n, r) => `Repostos ${n} locais guardados. ${tr(r)}`],
  [/^Restored (\d+) catch(?:es)? from the backup\.$/, (m, n) => `Repostas ${n} capturas da cópia.`],
  [/^Saved “(.+)”\. It's now in the Fishing at list too\.$/, (m, n) => `“${n}” guardado. Já aparece também em "A pescar em".`],
  [/^You're outside the Southern IFCA area \((.+)\)\. .*$/, (m, a) => `Estás fora da área da Southern IFCA (${a}). As regras do robalo e da juliana abaixo aplicam-se em toda a Inglaterra, mas os tamanhos mínimos podem mudar localmente. Confirma na IFCA local antes de levar peixe.`],
  [/^You're outside the UK \((.+)\), so these rules don't apply\..*$/, (m, a) => `Estás fora do Reino Unido (${a}), por isso estas regras não se aplicam. Vê as regras de pesca locais antes de levar alguma coisa.`],
  [/^⭐ Your (\d+) catches: (.*)$/, (m, n, r) => `⭐ As tuas ${n} capturas: ${r.split(' · ').map(x => x.startsWith('on ') ? 'com ' + tr(x.slice(3)) : tr(x)).join(' · ')}`],
  [/^(\S.*?) \((\d+)%\)$/, (m, a, n) => `${tr(a)} (${n}%)`],
  [/^on (.+)$/, (m, a) => `com ${tr(a)}`],
  [/^(.+) × (\d+)$/, (m, a, n) => `${tr(a)} × ${n}`],
  [/^Photo: (.*)$/s, (m, a) => `Foto: ${a.replace('Unknown author', 'Autor desconhecido')}`],
  [/^Rules checked (\d+) (\w+) (\d+)$/, (m, d, mo, y) => `Regras verificadas a ${d} ${tr(mo)} ${y}`]
];
function tr(s) {
  if (LANG !== 'pt' || s == null) return s;
  const lead = s.match(/^\s*/)[0], trail = s.match(/\s*$/)[0], k = s.replace(/\s+/g, ' ').trim();
  if (!k || !/[A-Za-z]/.test(k)) return s;
  const r = trCore(k); return r == null ? s : lead + r + trail;
}
function trCore(k, depth = 0) {
  if (PT[k] != null) return PT[k];
  const nums = [], tk = k.replace(/\d+(?:[.,:]\d+)*/g, x => { nums.push(x); return '#'; });
  if (nums.length && PT[tk] != null) { let i = 0; return PT[tk].replace(/#/g, () => nums[i] != null ? nums[i++] : '#'); }
  for (const [rx, f] of PT_RX) { const m = k.match(rx); if (m) return f(...m); }
  if (depth < 3) for (const sep of [' · ', ', ', ' / ', ' – ']) if (k.includes(sep)) {
    const parts = k.split(sep), out = parts.map(p => trCore(p, depth + 1)); if (out.some(x => x != null)) return out.map((x, i) => x == null ? parts[i] : x).join(sep);
  }
  const a = /^[A-Z]/.test(k) ? lc1(k) : uc1(k);
  if (a !== k) { const r = PT[a] != null ? PT[a] : (nums.length && PT[a.replace(/\d+(?:[.,:]\d+)*/g, '#')] != null ? trCore(a, depth + 1) : null); if (r != null) return /^[A-Z]/.test(k) ? uc1(r) : lc1(r); }
  // a fish shown as "English (Português)": show the Portuguese name
  const fm = k.match(/^([A-Z][^()]+) \(([A-ZÀ-ÿ][^()]+)\)$/); if (fm && FISH_PT.concat(FISH_MAD).some(f => f.n === k)) return uc1(fm[2]);
  return null;
}

// ---------- state (the watch keeps "now" fresh) ----------
let now = Date.now(), tp = ukParts(now);
function tick() { now = Date.now(); tp = ukParts(now); }
const isToday = s => s.y === tp.y && s.m === tp.m && s.d === tp.d;
const addDays = (s, n) => { const x = new Date(Date.UTC(s.y, s.m, s.d + n)); return { y: x.getUTCFullYear(), m: x.getUTCMonth(), d: x.getUTCDate(), dow: x.getUTCDay() }; };
